(()=>{const refs=window.MUSIE_DRAWINGS=[{"label":"A.05 \u00b7 Cabinet plan","src":"data:image/webp;base64,"},{"label":"A.08 \u00b7 Countertop","src":"data:image/webp;base64,"},{"label":"A.10 \u00b7 Sink wall","src":"data:image/webp;base64,"},{"label":"A.12 \u00b7 Range wall","src":"data:image/webp;base64,"},{"label":"A.13 \u00b7 Peninsula","src":"data:image/webp;base64,"},{"label":"A.14 \u00b7 Peninsula spec","src":"data:image/webp;base64,"},{"label":"A.15 \u00b7 Dining side","src":"data:image/webp;base64,"},{"label":"A.16 \u00b7 Dining spec","src":"data:image/webp;base64,"}];const maps={overview:1,sink:2,range:3,peninsula:4,plan:0};const panel=document.getElementById("source-drawing"),toggle=document.getElementById("source-ref-toggle"),img=document.getElementById("source-drawing-image"),caption=document.getElementById("source-drawing-caption");const choose=i=>{const r=refs[i];img.src=r.src;img.alt=r.label+" source from the kitchen v.4 PDF";caption.textContent=r.label;panel.querySelectorAll("[data-source-ref]").forEach(b=>b.setAttribute("aria-pressed",String(Number(b.dataset.sourceRef)===i)))};const open=()=>{panel.hidden=false;toggle.setAttribute("aria-expanded","true")},close=()=>{panel.hidden=true;toggle.setAttribute("aria-expanded","false")};toggle.addEventListener("click",()=>{if(panel.hidden){const active=document.querySelector(".view-tabs [data-view].active")?.dataset.view||"sink";choose(maps[active]??2);open()}else close()});document.getElementById("source-ref-close").addEventListener("click",close);panel.querySelectorAll("[data-source-ref]").forEach(b=>b.addEventListener("click",()=>choose(Number(b.dataset.sourceRef))));document.querySelector(".view-tabs").addEventListener("click",e=>{const b=e.target.closest("[data-view]");if(b&&!panel.hidden)choose(maps[b.dataset.view]??2)});})();
